export class FluentType{constructor(value){this.value=value}valueOf(){return this.value}}export class FluentNone extends FluentType{constructor(value="???"){super(value)}toString(scope){return`{${this.value}}`}}export class FluentNumber extends FluentType{constructor(value,opts={}){super(value);this.opts=opts}toString(scope){try{const nf=scope.memoizeIntlObject(Intl.NumberFormat,this.opts);return nf.format(this.value)}catch(err){scope.reportError(err);return this.value.toString(10)}}}export class FluentDateTime extends FluentType{constructor(value,opts={}){super(value);this.opts=opts}toString(scope){try{const dtf=scope.memoizeIntlObject(Intl.DateTimeFormat,this.opts);return dtf.format(this.value)}catch(err){scope.reportError(err);return new Date(this.value).toISOString()}}}